namespace HmisWeb.Services
{
    /// <summary>
    /// Values needed to create one legacy REGISTER row (one hospital visit).
    ///
    /// PATIENT.CODE (PCODE) is the permanent patient code / MRNo. REGISTER.REGNO
    /// is the visit identity and is generated by
    /// <see cref="ICommonService.CreateRegisterVisitAsync"/>.
    /// </summary>
    public class RegisterVisitRequest
    {
        /// <summary>'O' outpatient, 'I' inpatient.</summary>
        public string Type { get; set; } = "O";

        /// <summary>Permanent patient code (PATIENT.CODE / PCODE).</summary>
        public string PCode { get; set; }

        /// <summary>PATIENT.id - stored in REGISTER.pid.</summary>
        public long PatientAppId { get; set; }

        public DateTime VisitDate { get; set; }

        /// <summary>Visit time, HH:mm. Defaults to the current time.</summary>
        public string VisitTime { get; set; }

        public string Diagnosis { get; set; }

        /// <summary>App INSTITUTION id; resolved to REGISTER.CID.</summary>
        public long? CompanyId { get; set; }

        /// <summary>App STAFF/Doctor id; resolved to REGISTER.CONCODE.</summary>
        public long? ConsultantId { get; set; }

        public string EmployeeCode { get; set; }
        public string EmployeeRelation { get; set; }
        public string ReferenceNo { get; set; }
        public DateTime? RefValid { get; set; }
        public string CardNo { get; set; }
        public string GuardianName { get; set; }
        public string GuardianRelation { get; set; }
        public string BedNo { get; set; }
        public string BedEntitlement { get; set; }

        /// <summary>Legacy CUSERID / BILLSTATUSBY.</summary>
        public string CUserId { get; set; }

        /// <summary>Legacy USERID (last updater).</summary>
        public string UserId { get; set; }

        /// <summary>Company/insurance status; 'A' for an active panel/credit visit.</summary>
        public string CStat { get; set; }
    }
}
